using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class ExternalIntegrationConnectionConfiguration:IEntityTypeConfiguration<ExternalIntegrationConnection>{public void Configure(EntityTypeBuilder<ExternalIntegrationConnection>b){b.ToTable("ExternalIntegrationConnections");b.HasKey(x=>x.Id);b.Property(x=>x.TenantId).HasMaxLength(30).IsRequired();b.Property(x=>x.DisplayName).HasMaxLength(200).IsRequired();b.Property(x=>x.AccountIdentifier).HasMaxLength(200).IsRequired();b.Property(x=>x.CredentialsJson).HasColumnType("nvarchar(max)").IsRequired();b.Property(x=>x.LastError).HasMaxLength(2000);b.HasIndex(x=>new{x.ShopId,x.Provider,x.AccountIdentifier}).IsUnique();}}
